import sys
from collections import Counter, deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    L = int(next(iterator))
    C = int(next(iterator))

    grid = []
    row_sums = []
    for _ in range(L):
        row = [next(iterator) for _ in range(C)]
        s = int(next(iterator))
        grid.append(row)
        row_sums.append(s)

    col_sums = [int(next(iterator)) for _ in range(C)]

    # Criamos as equações: L linhas e C colunas
    # Cada equação terá:
    # - unknown_counts: dict {var: count}
    # - remaining_sum: int
    eq_unknown_counts = []
    eq_rem_sums = []
    var_to_eqs = {}

    # Linhas: índices 0 a L-1
    for r in range(L):
        counts = Counter(grid[r])
        eq_unknown_counts.append(counts)
        eq_rem_sums.append(row_sums[r])
        for var in counts:
            if var not in var_to_eqs:
                var_to_eqs[var] = []
            var_to_eqs[var].append(r)

    # Colunas: índices L a L+C-1
    for c in range(C):
        col_vars = [grid[r][c] for r in range(L)]
        counts = Counter(col_vars)
        eq_idx = L + c
        eq_unknown_counts.append(counts)
        eq_rem_sums.append(col_sums[c])
        for var in counts:
            if var not in var_to_eqs:
                var_to_eqs[var] = []
            var_to_eqs[var].append(eq_idx)

    values = {}
    queue = deque()

    for eq_idx in range(L + C):
        if len(eq_unknown_counts[eq_idx]) == 1:
            queue.append(eq_idx)

    while queue:
        eq_idx = queue.popleft()
        if len(eq_unknown_counts[eq_idx]) != 1:
            continue

        var, cnt = next(iter(eq_unknown_counts[eq_idx].items()))
        if var in values:
            continue

        val = eq_rem_sums[eq_idx] // cnt
        values[var] = val

        for related_eq in var_to_eqs[var]:
            if var in eq_unknown_counts[related_eq]:
                c = eq_unknown_counts[related_eq].pop(var)
                eq_rem_sums[related_eq] -= val * c
                if len(eq_unknown_counts[related_eq]) == 1:
                    queue.append(related_eq)

    for var in sorted(values.keys()):
        print(f"{var} {values[var]}")

if __name__ == '__main__':
    solve()
